const API = "/admin/research";
const STATUS_LABELS: Record<string, string> = { new: "جديد", accepted: "مقبول", searching_sources: "البحث عن المصادر", writing: "الكتابة", review: "المراجعة", formatting: "التنسيق", plagiarism_check: "فحص الاستلال", completed: "مكتمل", delivered: "تم التسليم", archived: "مؤرشف" };
const TYPE_LABELS: Record<string, string> = { graduation: "مشروع تخرج", diploma: "دبلوم", bachelor: "بكالوريوس", master: "ماجستير", phd: "دكتوراه", article: "مقالة", conference: "بحث مؤتمر", report: "تقرير" };
const MODES: Record<string, string> = { dashboard: "لوحة التحكم", new: "طلب بحث جديد", orders: "طلبات الأبحاث", library: "مكتبة الأبحاث", sources: "مكتبة المصادر", ai: "المساعد الذكي", writers: "الكتّاب", supervisors: "المشرفون", universities: "الجامعات", templates: "قوالب الأبحاث", plagiarism: "تقارير الاستلال", citations: "التوثيق والمراجع", portal: "بوابة العميل", reports: "التقارير", settings: "الإعدادات" };

function modeFromPath() { const parts = window.location.pathname.split("/").filter(Boolean); return parts[2] || "dashboard"; }
function statusBadge(status: string) { const variant = ["completed", "delivered"].includes(status) ? "default" : ["new", "accepted", "searching_sources"].includes(status) ? "secondary" : "outline"; return <Badge variant={variant}>{STATUS_LABELS[status] || status}</Badge>; }
function researchFetch<T>(path: string, init?: RequestInit) { return adminFetch<T>(`${API}${path}`, init); }

function Metric({ label, value, icon: Icon, hint }: { label: string; value: string | number; icon: any; hint?: string }) {
  return <div className="rounded-xl bg-card p-4 shadow-sm"><div className="flex items-start justify-between gap-3"><div><p className="text-sm text-muted-foreground">{label}</p><p className="mt-2 text-2xl font-bold tabular-nums">{value}</p>{hint ? <p className="mt-1 text-xs text-muted-foreground">{hint}</p> : null}</div><span className="flex h-10 w-10 items-center justify-center rounded-lg bg-violet-500/10 text-violet-600 dark:text-violet-300"><Icon className="h-5 w-5" /></span></div></div>;
}

function Dashboard() {
  const { data, isLoading, refetch } = useQuery<any>({ queryKey: ["research", "dashboard"], queryFn: () => researchFetch("/dashboard"), refetchInterval: 60_000 });
  if (isLoading) return <div className="grid gap-4 md:grid-cols-4">{Array.from({ length: 8 }).map((_, i) => <Skeleton key={i} className="h-28" />)}</div>;
  const summary = data?.summary || {};
  return <div className="space-y-5">
    <div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-bold">مساحة تشغيل البحوث الأكاديمية</h2><p className="mt-1 text-sm text-muted-foreground">الطلبات، الفصول، المصادر والمالية من سجل مركزي واحد.</p></div><Button variant="outline" onClick={() => refetch()}><RefreshCw className="ml-2 h-4 w-4" />تحديث</Button></div>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-6"><Metric label="إجمالي الأبحاث" value={summary.total || 0} icon={BookOpen} /><Metric label="قيد التنفيذ" value={summary.inProgress || 0} icon={Clock3} /><Metric label="بانتظار القبول" value={summary.pending || 0} icon={AlertTriangle} /><Metric label="المكتملة" value={summary.completed || 0} icon={CheckCircle2} /><Metric label="الإيراد المقبوض" value={formatCurrency(summary.revenue || 0)} icon={CircleDollarSign} /><Metric label="متوسط الإنجاز" value={`${summary.avgProgress || 0}%`} icon={BarChart3} /></div>
    <div className="grid gap-5 xl:grid-cols-[minmax(0,1.7fr)_minmax(280px,.8fr)]">
      <section className="rounded-xl bg-card p-4 shadow-sm"><div className="mb-4 flex items-center justify-between"><h3 className="font-bold">أحدث الطلبات</h3><a className="text-sm text-violet-600 hover:underline" href="/admin/research/orders">عرض الكل</a></div><div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>رقم البحث</TableHead><TableHead>العنوان</TableHead><TableHead>الجامعة</TableHead><TableHead>الحالة</TableHead><TableHead>التقدم</TableHead></TableRow></TableHeader><TableBody>{(data?.recent || []).map((item: any) => <TableRow key={item.id}><TableCell className="font-mono text-xs">{item.researchNo}</TableCell><TableCell className="max-w-[280px] truncate font-medium">{item.title}</TableCell><TableCell>{item.universityName || "—"}</TableCell><TableCell>{statusBadge(item.status)}</TableCell><TableCell><div className="flex min-w-28 items-center gap-2"><Progress value={item.progress} /><span className="text-xs">{item.progress}%</span></div></TableCell></TableRow>)}</TableBody></Table></div></section>
      <div className="space-y-5"><section className="rounded-xl bg-card p-4 shadow-sm"><h3 className="font-bold">توزيع مراحل العمل</h3><div className="mt-4 space-y-3">{(data?.byStatus || []).map((row: any) => <div key={row.status} className="flex items-center justify-between text-sm"><span>{STATUS_LABELS[row.status] || row.status}</span><Badge variant="outline">{row.count}</Badge></div>)}</div></section><section className="rounded-xl bg-card p-4 shadow-sm"><h3 className="font-bold">أفضل الكتّاب</h3><div className="mt-4 space-y-3">{(data?.writers || []).map((writer: any) => <div key={writer.id} className="flex items-center justify-between"><div><p className="text-sm font-medium">{writer.name || writer.username}</p><p className="text-xs text-muted-foreground">{Math.round((writer.minutes || 0) / 60)} ساعة عمل</p></div><Badge>{writer.completed} مكتمل</Badge></div>)}</div></section></div>
    </div>
  </div>;
}

const initialOrder = { customerName: "", phone: "", title: "", researchType: "graduation", universityId: "", universityName: "", college: "", department: "", supervisorName: "", language: "ar", researchField: "", keywords: "", requiredPages: 30, deadline: "", citationStyle: "APA7", urgency: "normal", estimatedPrice: 0, deposit: 0, notes: "", files: [] as any[] };
const ORDER_FIELD_LABELS: Record<string, string> = {
  customerName: "اسم الزبون", phone: "رقم الهاتف", title: "عنوان البحث", researchType: "نوع البحث",
  universityId: "الجامعة", universityName: "اسم الجامعة", college: "الكلية", department: "القسم",
  supervisorName: "اسم المشرف", language: "اللغة", researchField: "المجال العلمي", requiredPages: "عدد الصفحات",
  deadline: "موعد التسليم", citationStyle: "نمط التوثيق", urgency: "مستوى الاستعجال", estimatedPrice: "السعر التقديري",
  deposit: "العربون", notes: "الملاحظات", files: "الملفات",
};
function normalizeOrderPayload(form: typeof initialOrder) {
  const optional = (value: string) => (value.trim() ? value.trim() : null);
  return {
    customerName: form.customerName.trim(),
    phone: form.phone.trim(),
    title: form.title.trim(),
    researchType: form.researchType,
    // Manual entry ("إدخال يدوي") leaves universityId empty → send null, not "".
    universityId: form.universityId ? Number(form.universityId) : null,
    universityName: form.universityName.trim(),
    college: optional(form.college),
    department: optional(form.department),
    supervisorName: optional(form.supervisorName),
    language: form.language,
    researchField: optional(form.researchField),
    keywords: form.keywords,
    requiredPages: Number(form.requiredPages) || 0,
    deadline: form.deadline || null,
    citationStyle: form.citationStyle,
    urgency: form.urgency,
    estimatedPrice: Number(form.estimatedPrice) || 0,
    deposit: Number(form.deposit) || 0,
    notes: optional(form.notes),
    files: form.files,
  };
}
function OrderForm() {
  const { toast } = useToast(); const [form, setForm] = useState(initialOrder); const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({}); const catalog = useQuery<any>({ queryKey: ["research", "catalog"], queryFn: () => researchFetch("/catalog") });
  const save = useMutation({
    mutationFn: () => researchFetch<any>("/orders", { method: "POST", body: JSON.stringify(normalizeOrderPayload(form)) }),
    onSuccess: (result) => { setFieldErrors({}); toast({ title: "تم إنشاء طلب البحث", description: result.order.researchNo }); window.location.href = "/admin/research/orders"; },
    onError: (error: any) => {
      const serverFields = error?.data?.fieldErrors && typeof error.data.fieldErrors === "object" ? error.data.fieldErrors as Record<string, string> : {};
      setFieldErrors(serverFields);
      toast({ title: "تعذر إنشاء الطلب", description: error?.data?.message || apiErrorMessage(error), variant: "destructive" });
    },
  });
  function update(key: string, value: unknown) { setForm((current) => ({ ...current, [key]: value })); setFieldErrors((current) => { if (!current[key]) return current; const next = { ...current }; delete next[key]; return next; }); }
  function submit() {
    const errors: Record<string, string> = {};
    if (form.customerName.trim().length < 2) errors.customerName = "اسم الزبون مطلوب (حرفان على الأقل)";
    if (form.phone.replace(/\D/g, "").length < 10) errors.phone = "رقم الهاتف غير مكتمل";
    if (form.title.trim().length < 5) errors.title = "عنوان البحث قصير جداً (5 أحرف على الأقل)";
    if (form.universityName.trim().length < 2) errors.universityName = "اسم الجامعة مطلوب";
    if (!(Number(form.requiredPages) >= 1)) errors.requiredPages = "عدد الصفحات يجب أن يكون 1 على الأقل";
    if (Number(form.estimatedPrice) < 0) errors.estimatedPrice = "السعر التقديري غير صحيح";
    if (Number(form.deposit) > Number(form.estimatedPrice)) errors.deposit = "العربون لا يمكن أن يتجاوز السعر التقديري";
    setFieldErrors(errors);
    if (Object.keys(errors).length) { toast({ title: "تحقق من الحقول المميزة", description: "يرجى تصحيح البيانات قبل الحفظ", variant: "destructive" }); return; }
    save.mutate();
  }
  const errText = (key: string) => (fieldErrors[key] ? <p className="mt-1 text-xs font-medium text-destructive">{fieldErrors[key]}</p> : null);
  async function filesSelected(files: FileList | null) { if (!files) return; const rows = await Promise.all([...files].map((file) => new Promise<any>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve({ title: file.name, fileName: file.name, fileUrl: reader.result, mimeType: file.type, fileType: "customer_upload" }); reader.onerror = reject; reader.readAsDataURL(file); }))); setForm((current) => ({ ...current, files: [...current.files, ...rows] })); }
  return <div className="mx-auto max-w-5xl space-y-5"><div><h2 className="text-xl font-bold">إنشاء طلب بحث جديد</h2><p className="mt-1 text-sm text-muted-foreground">ينشئ ملف عميل وفاتورة وفصولاً ورقم متابعة QR ضمن النظام المركزي.</p></div>
    {Object.keys(fieldErrors).length ? <div className="rounded-xl border border-destructive/40 bg-destructive/5 p-4"><p className="mb-2 flex items-center gap-2 text-sm font-bold text-destructive"><AlertTriangle className="h-4 w-4" />يرجى تصحيح الحقول التالية</p><ul className="space-y-1 pr-5 text-sm text-destructive">{Object.entries(fieldErrors).map(([key, message]) => <li key={key} className="list-disc"><strong>{ORDER_FIELD_LABELS[key] || key}:</strong> {message}</li>)}</ul></div> : null}
    <div className="rounded-xl bg-card p-5 shadow-sm"><div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
    <div className="lg:col-span-2"><Label>عنوان البحث</Label><Input className="mt-2" value={form.title} onChange={(e) => update("title", e.target.value)} />{errText("title")}</div><div><Label>نوع البحث</Label><Select value={form.researchType} onValueChange={(value) => update("researchType", value)}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent>{Object.entries(TYPE_LABELS).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div>
    <div><Label>اسم الزبون</Label><Input className="mt-2" value={form.customerName} onChange={(e) => update("customerName", e.target.value)} />{errText("customerName")}</div><div><Label>رقم الهاتف</Label><Input dir="ltr" className="mt-2 text-right" value={form.phone} onChange={(e) => update("phone", e.target.value)} />{errText("phone")}</div><div><Label>الجامعة</Label><Select value={form.universityId || "manual"} onValueChange={(value) => { const uni = catalog.data?.universities?.find((item: any) => String(item.id) === value); setForm((current) => ({ ...current, universityId: value === "manual" ? "" : value, universityName: uni?.nameAr || current.universityName })); }}><SelectTrigger className="mt-2"><SelectValue placeholder="اختر الجامعة" /></SelectTrigger><SelectContent><SelectItem value="manual">إدخال يدوي</SelectItem>{(catalog.data?.universities || []).map((item: any) => <SelectItem key={item.id} value={String(item.id)}>{item.nameAr}</SelectItem>)}</SelectContent></Select></div>
    <div><Label>اسم الجامعة</Label><Input className="mt-2" value={form.universityName} onChange={(e) => update("universityName", e.target.value)} />{errText("universityName")}</div><div><Label>الكلية</Label><Input className="mt-2" value={form.college} onChange={(e) => update("college", e.target.value)} /></div><div><Label>القسم</Label><Input className="mt-2" value={form.department} onChange={(e) => update("department", e.target.value)} /></div>
    <div><Label>اسم المشرف</Label><Input className="mt-2" value={form.supervisorName} onChange={(e) => update("supervisorName", e.target.value)} /></div><div><Label>المجال العلمي</Label><Input className="mt-2" value={form.researchField} onChange={(e) => update("researchField", e.target.value)} /></div><div><Label>الكلمات المفتاحية</Label><Input className="mt-2" value={form.keywords} onChange={(e) => update("keywords", e.target.value)} placeholder="افصل بينها بفاصلة" /></div>
    <div><Label>اللغة</Label><Select value={form.language} onValueChange={(value) => update("language", value)}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="ar">العربية</SelectItem><SelectItem value="en">الإنجليزية</SelectItem><SelectItem value="ku">الكردية</SelectItem><SelectItem value="other">أخرى</SelectItem></SelectContent></Select></div><div><Label>نمط التوثيق</Label><Select value={form.citationStyle} onValueChange={(value) => update("citationStyle", value)}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent>{["APA7", "IEEE", "MLA", "Harvard", "Chicago"].map((item) => <SelectItem key={item} value={item}>{item}</SelectItem>)}</SelectContent></Select></div><div><Label>مستوى الاستعجال</Label><Select value={form.urgency} onValueChange={(value) => update("urgency", value)}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="normal">اعتيادي</SelectItem><SelectItem value="urgent">مستعجل</SelectItem><SelectItem value="critical">عاجل جداً</SelectItem></SelectContent></Select></div>
    <div><Label>عدد الصفحات</Label><Input className="mt-2" type="number" value={form.requiredPages} onChange={(e) => update("requiredPages", Number(e.target.value))} />{errText("requiredPages")}</div><div><Label>موعد التسليم</Label><Input className="mt-2" type="date" value={form.deadline} onChange={(e) => update("deadline", e.target.value)} />{errText("deadline")}</div><div><Label>السعر التقديري</Label><Input className="mt-2" type="number" value={form.estimatedPrice} onChange={(e) => update("estimatedPrice", Number(e.target.value))} />{errText("estimatedPrice")}</div><div><Label>العربون</Label><Input className="mt-2" type="number" value={form.deposit} onChange={(e) => update("deposit", Number(e.target.value))} />{errText("deposit")}</div>
    <div className="sm:col-span-2 lg:col-span-3"><Label>الملاحظات</Label><Textarea className="mt-2" value={form.notes} onChange={(e) => update("notes", e.target.value)} /></div><div className="sm:col-span-2 lg:col-span-3"><Label htmlFor="research-files">ملفات العميل</Label><label htmlFor="research-files" className="mt-2 flex min-h-24 cursor-pointer items-center justify-center rounded-lg border border-dashed border-border text-sm text-muted-foreground hover:border-violet-500"><Upload className="ml-2 h-4 w-4" />Word، PDF، ZIP، صور أو بيانات</label><input id="research-files" type="file" multiple className="sr-only" onChange={(e) => filesSelected(e.target.files)} /><div className="mt-2 flex flex-wrap gap-2">{form.files.map((file) => <Badge key={file.fileName} variant="outline">{file.fileName}</Badge>)}</div></div>
  </div><div className="mt-5 flex justify-end"><Button disabled={save.isPending} onClick={submit}>{save.isPending ? <Loader2 className="ml-2 h-4 w-4 animate-spin" /> : <Plus className="ml-2 h-4 w-4" />}إنشاء الطلب والفاتورة</Button></div></div></div>;
}

function ResearchWorkspace({ id, onClose }: { id: number; onClose: () => void }) {
  const { toast } = useToast(); const client = useQueryClient(); const [paymentOpen, setPaymentOpen] = useState(false); const [payment, setPayment] = useState({ amount: 0, paymentMethod: "cash" }); const [message, setMessage] = useState(""); const [plagiarism, setPlagiarism] = useState({ similarityPercentage: 0, provider: "manual", reportUrl: "", notes: "" });
  const query = useQuery<any>({ queryKey: ["research", "order", id], queryFn: () => researchFetch(`/orders/${id}`) });
  const catalog = useQuery<any>({ queryKey: ["research", "catalog"], queryFn: () => researchFetch("/catalog") });
  const patch = useMutation({ mutationFn: (changes: any) => researchFetch(`/orders/${id}`, { method: "PATCH", body: JSON.stringify(changes) }), onSuccess: () => { client.invalidateQueries({ queryKey: ["research", "order", id] }); toast({ title: "تم تحديث البحث" }); }, onError: (error) => toast({ title: "تعذر التحديث", description: apiErrorMessage(error), variant: "destructive" }) });
  const pay = useMutation({ mutationFn: () => researchFetch(`/orders/${id}/payment`, { method: "POST", body: JSON.stringify(payment) }), onSuccess: () => { setPaymentOpen(false); client.invalidateQueries({ queryKey: ["research", "order", id] }); toast({ title: "تم تسجيل الدفعة" }); }, onError: (error) => toast({ title: "تعذر تسجيل الدفعة", description: apiErrorMessage(error), variant: "destructive" }) });
  const sendMessage = useMutation({ mutationFn: () => researchFetch("/messages", { method: "POST", body: JSON.stringify({ orderId: id, message }) }), onSuccess: () => { setMessage(""); query.refetch(); toast({ title: "تم إرسال الرسالة" }); }, onError: (error) => toast({ title: "تعذر إرسال الرسالة", description: apiErrorMessage(error), variant: "destructive" }) });
  const savePlagiarism = useMutation({ mutationFn: () => researchFetch("/plagiarism", { method: "POST", body: JSON.stringify({ orderId: id, ...plagiarism }) }), onSuccess: () => { query.refetch(); toast({ title: "تم حفظ تقرير الاستلال" }); }, onError: (error) => toast({ title: "تعذر حفظ التقرير", description: apiErrorMessage(error), variant: "destructive" }) });
  const citations = useMutation({ mutationFn: () => researchFetch(`/citations/${id}`, { method: "POST" }), onSuccess: (result: any) => { query.refetch(); toast({ title: "تم توليد قائمة المراجع", description: `${result.citations?.length || 0} مرجع` }); }, onError: (error) => toast({ title: "تعذر توليد المراجع", description: apiErrorMessage(error), variant: "destructive" }) });
  async function uploadFiles(files: FileList | null) { if (!files) return; for (const file of [...files]) { const fileUrl = await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file); }); await researchFetch("/files", { method: "POST", body: JSON.stringify({ orderId: id, title: file.name, fileName: file.name, fileUrl, mimeType: file.type, fileSize: file.size, fileType: "draft", isCustomerVisible: false }) }); } await query.refetch(); toast({ title: "تم رفع الملفات وحفظ إصدارها" }); }
  if (query.isLoading) return <Skeleton className="h-[620px]" />; const data = query.data; const order = data.order;
  return <div className="space-y-5"><div className="sticky top-0 z-20 flex flex-wrap items-center justify-between gap-3 rounded-xl bg-card p-4 shadow-sm"><div><Button variant="ghost" size="sm" onClick={onClose}>العودة للطلبات</Button><h2 className="mt-1 text-lg font-bold">{order.title}</h2><p className="font-mono text-xs text-violet-600">{order.researchNo}</p></div><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={() => openResearchReceiptPrint({ order, chapters: data.chapters, sources: data.sources })}><Printer className="ml-2 h-4 w-4" />طباعة ملخص</Button><Button variant="outline" onClick={() => setPaymentOpen(true)}><WalletCards className="ml-2 h-4 w-4" />استلام دفعة</Button><Select value={order.status} onValueChange={(status) => patch.mutate({ status })}><SelectTrigger className="w-44"><SelectValue /></SelectTrigger><SelectContent>{Object.entries(STATUS_LABELS).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div></div>
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Metric label="التقدم" value={`${order.progress}%`} icon={BarChart3} /><Metric label="المصادر" value={order.sourceCount} icon={Library} /><Metric label="الفصول" value={order.chapterCount} icon={BookOpen} /><Metric label="المدفوع" value={formatCurrency(order.paidAmount)} icon={CircleDollarSign} /><Metric label="المتبقي" value={formatCurrency(order.remainingAmount)} icon={Receipt} /></div>
    <Tabs defaultValue="chapters" dir="rtl"><TabsList className="h-auto flex-wrap"><TabsTrigger value="chapters">الفصول</TabsTrigger><TabsTrigger value="sources">المصادر</TabsTrigger><TabsTrigger value="files">الملفات</TabsTrigger><TabsTrigger value="team">الفريق</TabsTrigger><TabsTrigger value="plagiarism">الاستلال</TabsTrigger><TabsTrigger value="messages">المراسلات</TabsTrigger><TabsTrigger value="timeline">النشاط</TabsTrigger></TabsList>
      <TabsContent value="chapters" className="rounded-xl bg-card p-4 shadow-sm"><div className="space-y-3">{data.chapters.map((chapter: any) => <div key={chapter.id} className="grid items-center gap-3 rounded-lg border border-border p-3 md:grid-cols-[minmax(180px,1fr)_140px_minmax(150px,1fr)_100px]"><div><strong className="text-sm">{chapter.title}</strong><p className="text-xs text-muted-foreground">الإصدار {chapter.currentVersion} · {chapter.wordCount} كلمة</p></div><Badge variant="outline">{chapter.status}</Badge><div className="flex items-center gap-2"><Progress value={chapter.progress} /><span className="text-xs">{chapter.progress}%</span></div><Button size="sm" variant="outline" onClick={() => { const progress = Math.min(100, chapter.progress + 25); researchFetch(`/chapters/${chapter.id}`, { method: "PATCH", body: JSON.stringify({ progress, status: progress >= 100 ? "completed" : "writing" }) }).then(() => query.refetch()); }}>تحديث</Button></div>)}</div></TabsContent>
      <TabsContent value="sources" className="rounded-xl bg-card p-4 shadow-sm"><div className="mb-4 flex flex-wrap items-center justify-between gap-2"><p className="text-sm text-muted-foreground">المصادر المعتمدة لهذا البحث</p><Button size="sm" variant="outline" disabled={!data.sources.length || citations.isPending} onClick={() => citations.mutate()}><Receipt className="ml-2 h-4 w-4" />توليد المراجع {order.citationStyle}</Button></div>{data.sources.length ? <div className="space-y-3">{data.sources.map((source: any) => <div key={source.id} className="rounded-lg border border-border p-3"><div className="flex items-start justify-between gap-3"><div><strong>{source.title}</strong><p className="mt-1 text-sm text-muted-foreground">{source.authors?.join("، ")} · {source.publicationYear || "د.ت"}</p></div><Badge variant="outline">{source.provider}</Badge></div>{source.doi ? <p className="mt-2 font-mono text-xs">DOI: {source.doi}</p> : null}</div>)}</div> : <p className="py-8 text-center text-muted-foreground">لم تُربط مصادر بعد. استخدم مكتبة المصادر.</p>}{data.citations?.length ? <div className="mt-5 border-t border-border pt-4"><h3 className="font-bold">قائمة المراجع</h3><ol className="mt-3 list-decimal space-y-2 pr-5 text-sm leading-6">{data.citations.map((citation: any) => <li key={citation.id}>{citation.bibliographyText}</li>)}</ol></div> : null}</TabsContent>
      <TabsContent value="files" className="rounded-xl bg-card p-4 shadow-sm"><div className="mb-4 flex items-center justify-between gap-3"><p className="text-sm text-muted-foreground">المسودات والنسخ النهائية محفوظة بإصدارات مستقلة.</p><label htmlFor={`research-workspace-files-${id}`} className="inline-flex h-9 cursor-pointer items-center rounded-md border border-input bg-background px-3 text-sm font-medium"><Upload className="ml-2 h-4 w-4" />رفع إصدار</label><input id={`research-workspace-files-${id}`} type="file" multiple className="sr-only" onChange={(event) => uploadFiles(event.target.files).catch((error) => toast({ title: "تعذر رفع الملف", description: apiErrorMessage(error), variant: "destructive" }))} /></div><div className="space-y-2">{data.files.map((file: any) => <a key={file.id} href={file.fileUrl} target="_blank" rel="noreferrer" className="flex items-center justify-between rounded-lg border border-border p-3 hover:bg-muted"><span className="flex items-center gap-2"><FileText className="h-4 w-4" />{file.title}</span><Badge variant="outline">v{file.version}</Badge></a>)}</div></TabsContent>
      <TabsContent value="team" className="rounded-xl bg-card p-4 shadow-sm"><div className="mb-4 grid gap-3 md:grid-cols-2 xl:grid-cols-5">{[["assignedWriterId", "الكاتب"], ["assignedReviewerId", "المراجع"], ["assignedProofreaderId", "المدقق اللغوي"], ["assignedFormatterId", "المنسق"], ["assignedSupervisorId", "المشرف"]].map(([key, label]) => <div key={key}><Label>{label}</Label><Select value={order[key] ? String(order[key]) : "none"} onValueChange={(value) => patch.mutate({ [key]: value === "none" ? null : Number(value) })}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="none">غير معين</SelectItem>{(catalog.data?.writers || []).map((staff: any) => <SelectItem key={staff.id} value={String(staff.id)}>{staff.name || staff.username}</SelectItem>)}</SelectContent></Select></div>)}</div><div className="grid gap-3 md:grid-cols-2">{data.assignments.map((row: any) => <div key={row.assignment.id} className="rounded-lg border border-border p-3"><strong>{row.staffName || row.username}</strong><p className="text-sm text-muted-foreground">{row.assignment.role} · {row.assignment.status}</p></div>)}</div></TabsContent>
      <TabsContent value="plagiarism" className="rounded-xl bg-card p-4 shadow-sm"><div className="mb-4 grid items-end gap-3 md:grid-cols-4"><div><Label>نسبة التشابه %</Label><Input className="mt-2" type="number" min={0} max={100} value={plagiarism.similarityPercentage} onChange={(e) => setPlagiarism((current) => ({ ...current, similarityPercentage: Number(e.target.value) }))} /></div><div><Label>مزود التقرير</Label><Input className="mt-2" value={plagiarism.provider} onChange={(e) => setPlagiarism((current) => ({ ...current, provider: e.target.value }))} /></div><div><Label>رابط التقرير</Label><Input className="mt-2" value={plagiarism.reportUrl} onChange={(e) => setPlagiarism((current) => ({ ...current, reportUrl: e.target.value }))} /></div><Button disabled={savePlagiarism.isPending} onClick={() => savePlagiarism.mutate()}><ShieldCheck className="ml-2 h-4 w-4" />حفظ الفحص</Button></div><div className="space-y-2">{data.plagiarism.map((report: any) => <div key={report.id} className="flex items-center justify-between rounded-lg border border-border p-3"><span>{report.provider || "فحص يدوي"} · {new Date(report.createdAt).toLocaleDateString("ar-IQ")}</span><Badge variant={Number(report.similarityPercentage) <= 20 ? "default" : "destructive"}>{report.similarityPercentage}%</Badge></div>)}</div></TabsContent>
      <TabsContent value="messages" className="rounded-xl bg-card p-4 shadow-sm"><div className="space-y-2">{data.messages.map((item: any) => <div key={item.id} className={`max-w-xl rounded-lg p-3 ${item.senderType === "customer" ? "bg-muted" : "bg-violet-500/10"}`}><strong className="text-sm">{item.senderName}</strong><p className="mt-1 text-sm">{item.message}</p></div>)}</div><div className="mt-4 flex gap-2"><Input value={message} onChange={(event) => setMessage(event.target.value)} placeholder="اكتب رسالة للزبون..." /><Button disabled={sendMessage.isPending || message.trim().length < 2} onClick={() => sendMessage.mutate()}><Send className="ml-2 h-4 w-4" />إرسال</Button></div></TabsContent>
      <TabsContent value="timeline" className="rounded-xl bg-card p-4 shadow-sm"><div className="space-y-3">{data.timeline.map((event: any) => <div key={event.id} className="flex gap-3"><span className="mt-1 h-2.5 w-2.5 shrink-0 rounded-full bg-violet-500" /><div><p className="text-sm font-medium">{event.title}</p><p className="text-xs text-muted-foreground">{event.actorName} · {new Date(event.createdAt).toLocaleString("ar-IQ")}</p></div></div>)}</div></TabsContent>
    </Tabs>
    <Dialog open={paymentOpen} onOpenChange={setPaymentOpen}><DialogContent dir="rtl"><DialogHeader><DialogTitle>استلام دفعة بحث</DialogTitle></DialogHeader><div className="space-y-4"><div><Label>المبلغ</Label><Input className="mt-2" type="number" value={payment.amount} onChange={(e) => setPayment((c) => ({ ...c, amount: Number(e.target.value) }))} /></div><div><Label>طريقة الدفع</Label><Select value={payment.paymentMethod} onValueChange={(value) => setPayment((c) => ({ ...c, paymentMethod: value }))}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="cash">نقداً</SelectItem><SelectItem value="transfer">تحويل</SelectItem><SelectItem value="card">بطاقة</SelectItem><SelectItem value="other">أخرى</SelectItem></SelectContent></Select></div></div><DialogFooter><Button disabled={pay.isPending || payment.amount <= 0} onClick={() => pay.mutate()}>تسجيل الدفعة</Button></DialogFooter></DialogContent></Dialog>
  </div>;
}

function Orders({ library = false }: { library?: boolean }) {
  const [search, setSearch] = useState(""); const [status, setStatus] = useState(library ? "completed" : "all"); const [selected, setSelected] = useState<number | null>(null);
  const query = useQuery<any>({ queryKey: ["research", "orders", search, status], queryFn: () => researchFetch(`/orders?search=${encodeURIComponent(search)}&status=${status === "all" ? "" : status}`) });
  if (selected) return <ResearchWorkspace id={selected} onClose={() => setSelected(null)} />;
  return <div className="space-y-5"><div className="flex flex-wrap items-center justify-between gap-3"><div><h2 className="text-xl font-bold">{library ? "مكتبة الأبحاث المكتملة" : "طلبات الأبحاث"}</h2><p className="mt-1 text-sm text-muted-foreground">بحث فوري برقم البحث والعنوان والعميل والجامعة.</p></div><Button asChild><a href="/admin/research/new"><Plus className="ml-2 h-4 w-4" />طلب جديد</a></Button></div><div className="flex flex-col gap-3 rounded-xl bg-card p-4 shadow-sm sm:flex-row"><div className="relative flex-1"><Search className="absolute right-3 top-3 h-4 w-4 text-muted-foreground" /><Input className="pr-10" value={search} onChange={(e) => setSearch(e.target.value)} placeholder="ابحث برقم البحث، العنوان، العميل أو الجامعة..." /></div><Select value={status} onValueChange={setStatus}><SelectTrigger className="sm:w-48"><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">كل الحالات</SelectItem>{Object.entries(STATUS_LABELS).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div>
    <div className="rounded-xl bg-card shadow-sm"><div className="overflow-x-auto"><Table><TableHeader><TableRow><TableHead>رقم البحث</TableHead><TableHead>العنوان</TableHead><TableHead>النوع</TableHead><TableHead>الجامعة</TableHead><TableHead>الموعد</TableHead><TableHead>الحالة</TableHead><TableHead>الإنجاز</TableHead><TableHead>المتبقي</TableHead></TableRow></TableHeader><TableBody>{query.isLoading ? <TableRow><TableCell colSpan={8}><Skeleton className="h-28" /></TableCell></TableRow> : query.data?.items?.length ? query.data.items.map((item: any) => <TableRow key={item.id} className="cursor-pointer" onClick={() => setSelected(item.id)}><TableCell className="font-mono text-xs text-violet-600">{item.researchNo}</TableCell><TableCell className="max-w-[300px] truncate font-medium">{item.title}</TableCell><TableCell>{TYPE_LABELS[item.researchType] || item.researchType}</TableCell><TableCell>{item.universityName}</TableCell><TableCell>{item.deadline || "—"}</TableCell><TableCell>{statusBadge(item.status)}</TableCell><TableCell><div className="flex min-w-28 items-center gap-2"><Progress value={item.progress} /><span className="text-xs">{item.progress}%</span></div></TableCell><TableCell>{formatCurrency(item.remainingAmount)}</TableCell></TableRow>) : <TableRow><TableCell colSpan={8} className="h-32 text-center text-muted-foreground">لا توجد أبحاث مطابقة.</TableCell></TableRow>}</TableBody></Table></div></div>
  </div>;
}

function SourcesCenter() {
  const { toast } = useToast(); const [q, setQ] = useState(""); const [provider, setProvider] = useState("all"); const [orderId, setOrderId] = useState(""); const [results, setResults] = useState<any[]>([]);
  const [filters, setFilters] = useState({ year: "", author: "", journal: "", language: "", category: "" });
  const orders = useQuery<any>({ queryKey: ["research", "source-orders"], queryFn: () => researchFetch("/orders?page=1") });
  const search = useMutation({ mutationFn: () => { const params = new URLSearchParams({ q, provider, ...filters }); return researchFetch<any>(`/sources/search?${params.toString()}`); }, onSuccess: (data) => setResults(data.results), onError: (error) => toast({ title: "تعذر البحث", description: apiErrorMessage(error), variant: "destructive" }) });
  const add = useMutation({ mutationFn: (source: any) => researchFetch(`/orders/${orderId}/sources`, { method: "POST", body: JSON.stringify({ source }) }), onSuccess: () => toast({ title: "تم حفظ المصدر وربطه بالبحث" }), onError: (error) => toast({ title: "تعذر حفظ المصدر", description: apiErrorMessage(error), variant: "destructive" }) });
  return <div className="space-y-5"><div><h2 className="text-xl font-bold">محرك البحث عن المصادر</h2><p className="mt-1 text-sm text-muted-foreground">نتائج موحدة من Crossref وOpenAlex وSemantic Scholar وPubMed وDOAJ وarXiv، مع وصول مباشر إلى Google Scholar.</p></div><div className="space-y-3 rounded-xl bg-card p-4 shadow-sm"><div className="grid gap-3 lg:grid-cols-[220px_180px_minmax(260px,1fr)_120px]"><Select value={orderId} onValueChange={setOrderId}><SelectTrigger><SelectValue placeholder="اختر البحث" /></SelectTrigger><SelectContent>{(orders.data?.items || []).map((item: any) => <SelectItem key={item.id} value={String(item.id)}>{item.researchNo}</SelectItem>)}</SelectContent></Select><Select value={provider} onValueChange={setProvider}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent><SelectItem value="all">كل القواعد</SelectItem><SelectItem value="crossref">Crossref</SelectItem><SelectItem value="openalex">OpenAlex</SelectItem><SelectItem value="semantic_scholar">Semantic Scholar</SelectItem><SelectItem value="pubmed">PubMed</SelectItem><SelectItem value="doaj">DOAJ</SelectItem><SelectItem value="arxiv">arXiv</SelectItem></SelectContent></Select><Input value={q} onChange={(e) => setQ(e.target.value)} placeholder="كلمة مفتاحية، عنوان أو DOI..." onKeyDown={(e) => e.key === "Enter" && q.length > 1 && search.mutate()} /><Button disabled={search.isPending || q.length < 2} onClick={() => search.mutate()}>{search.isPending ? <Loader2 className="ml-2 h-4 w-4 animate-spin" /> : <Search className="ml-2 h-4 w-4" />}بحث</Button></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Input value={filters.author} onChange={(e) => setFilters((current) => ({ ...current, author: e.target.value }))} placeholder="المؤلف" /><Input value={filters.journal} onChange={(e) => setFilters((current) => ({ ...current, journal: e.target.value }))} placeholder="المجلة" /><Input inputMode="numeric" value={filters.year} onChange={(e) => setFilters((current) => ({ ...current, year: e.target.value }))} placeholder="السنة" /><Input value={filters.language} onChange={(e) => setFilters((current) => ({ ...current, language: e.target.value }))} placeholder="اللغة" /><Input value={filters.category} onChange={(e) => setFilters((current) => ({ ...current, category: e.target.value }))} placeholder="التصنيف" /></div></div>{q.length > 1 ? <div className="flex flex-wrap items-center gap-2 text-sm text-muted-foreground"><span>بحث إضافي:</span><Button variant="outline" size="sm" asChild><a href={`https://scholar.google.com/scholar?q=${encodeURIComponent([q, filters.author, filters.journal].filter(Boolean).join(" "))}`} target="_blank" rel="noreferrer">Google Scholar <ExternalLink className="mr-2 h-3.5 w-3.5" /></a></Button></div> : null}<div className="space-y-3">{results.map((source) => <article key={`${source.provider}:${source.externalId}`} className="rounded-xl bg-card p-4 shadow-sm"><div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between"><div className="min-w-0"><div className="flex flex-wrap gap-2"><Badge variant="outline">{source.provider}</Badge>{source.openAccess ? <Badge>PDF متاح</Badge> : null}{source.year ? <Badge variant="secondary">{source.year}</Badge> : null}</div><h3 className="mt-3 font-bold leading-7">{source.title}</h3><p className="mt-1 text-sm text-muted-foreground">{source.authors?.join("، ") || "مؤلف غير مسجل"}{source.journal ? ` · ${source.journal}` : ""}</p>{source.abstract ? <p className="mt-3 line-clamp-3 max-w-4xl text-sm leading-6 text-muted-foreground">{source.abstract}</p> : null}{source.doi ? <p className="mt-2 font-mono text-xs">DOI: {source.doi}</p> : null}</div><div className="flex shrink-0 gap-2">{source.url ? <Button variant="outline" size="sm" asChild><a href={source.url} target="_blank" rel="noreferrer"><ExternalLink className="ml-2 h-4 w-4" />فتح</a></Button> : null}<Button size="sm" disabled={!orderId || add.isPending} onClick={() => add.mutate(source)}><Plus className="ml-2 h-4 w-4" />إضافة</Button></div></div></article>)}</div></div>;
}

function AiCenter() {
  const { toast } = useToast(); const [orderId, setOrderId] = useState(""); const [action, setAction] = useState("literature_review"); const [prompt, setPrompt] = useState(""); const [selected, setSelected] = useState<number[]>([]); const [output, setOutput] = useState("");
  const orders = useQuery<any>({ queryKey: ["research", "ai-orders"], queryFn: () => researchFetch("/orders") }); const detail = useQuery<any>({ queryKey: ["research", "ai-detail", orderId], queryFn: () => researchFetch(`/orders/${orderId}`), enabled: Boolean(orderId) });
  const generate = useMutation({ mutationFn: () => researchFetch<any>("/ai", { method: "POST", body: JSON.stringify({ orderId, action, prompt, sourceIds: selected }) }), onSuccess: (data) => setOutput(data.output), onError: (error) => toast({ title: "تعذر التوليد", description: apiErrorMessage(error), variant: "destructive" }) });
  return <div className="grid gap-5 xl:grid-cols-[360px_minmax(0,1fr)]"><aside className="space-y-4 rounded-xl bg-card p-4 shadow-sm"><div><h2 className="font-bold">مساعد البحث الأكاديمي</h2><p className="mt-1 text-sm text-muted-foreground">لا يعمل دون مصادر مرتبطة، ولا يسمح بإشارات مرجعية خارجها.</p></div><div><Label>البحث</Label><Select value={orderId} onValueChange={(value) => { setOrderId(value); setSelected([]); }}><SelectTrigger className="mt-2"><SelectValue placeholder="اختر البحث" /></SelectTrigger><SelectContent>{(orders.data?.items || []).map((item: any) => <SelectItem key={item.id} value={String(item.id)}>{item.researchNo}</SelectItem>)}</SelectContent></Select></div><div><Label>الإجراء</Label><Select value={action} onValueChange={setAction}><SelectTrigger className="mt-2"><SelectValue /></SelectTrigger><SelectContent>{[["title", "توليد أو تحسين العنوان"], ["abstract", "إنشاء الملخص"], ["introduction", "كتابة المقدمة"], ["literature_review", "مراجعة الأدبيات"], ["methodology", "المنهجية"], ["discussion", "المناقشة"], ["conclusion", "الخاتمة والتوصيات"], ["research_questions", "أسئلة البحث"], ["objectives", "الأهداف"], ["hypothesis", "الفرضيات"], ["limitations", "المحددات"], ["future_work", "الأعمال المستقبلية"], ["keywords", "استخراج الكلمات المفتاحية"], ["rewrite", "إعادة صياغة أكاديمية"], ["expand", "توسيع النص"], ["shorten", "اختصار النص"], ["grammar", "التدقيق اللغوي"], ["translate", "ترجمة"], ["summarize", "تلخيص"]].map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select></div><div><Label>المصادر المسموحة</Label><div className="mt-2 max-h-64 space-y-2 overflow-y-auto">{(detail.data?.sources || []).map((source: any) => <label key={source.id} className="flex cursor-pointer items-start gap-2 rounded-lg border border-border p-2 text-sm"><Checkbox checked={selected.includes(source.id)} onCheckedChange={(checked) => setSelected((current) => checked ? [...current, source.id] : current.filter((id) => id !== source.id))} /><span className="line-clamp-2">{source.title}</span></label>)}</div></div></aside><section className="rounded-xl bg-card p-4 shadow-sm"><Textarea className="min-h-44" value={prompt} onChange={(e) => setPrompt(e.target.value)} placeholder="اكتب المطلوب بدقة، وسيستخدم المساعد المصادر المحددة فقط..." /><div className="mt-3 flex justify-end"><Button disabled={generate.isPending || !orderId || selected.length === 0 || prompt.length < 2} onClick={() => generate.mutate()}>{generate.isPending ? <Loader2 className="ml-2 h-4 w-4 animate-spin" /> : <Sparkles className="ml-2 h-4 w-4" />}توليد موثق</Button></div>{output ? <div className="mt-5 whitespace-pre-wrap rounded-lg border border-border bg-muted/40 p-4 text-sm leading-7">{output}</div> : <div className="flex min-h-80 items-center justify-center text-center text-muted-foreground"><div><Bot className="mx-auto mb-3 h-10 w-10 text-violet-500" /><p>اختر البحث والمصادر ثم اكتب المطلوب.</p></div></div>}</section></div>;
}

function CatalogPage({ mode }: { mode: string }) {
  const { toast } = useToast(); const catalog = useQuery<any>({ queryKey: ["research", "catalog"], queryFn: () => researchFetch("/catalog") }); const [university, setUniversity] = useState({ nameAr: "", nameEn: "", country: "العراق", city: "" }); const [template, setTemplate] = useState({ name: "", code: "", researchType: "graduation", language: "ar", citationStyle: "APA7" });
  const saveUniversity = useMutation({ mutationFn: () => researchFetch("/universities", { method: "POST", body: JSON.stringify(university) }), onSuccess: () => { catalog.refetch(); setUniversity({ nameAr: "", nameEn: "", country: "العراق", city: "" }); toast({ title: "تم حفظ الجامعة" }); } });
  const saveTemplate = useMutation({ mutationFn: () => researchFetch("/templates", { method: "POST", body: JSON.stringify(template) }), onSuccess: () => { catalog.refetch(); setTemplate({ name: "", code: "", researchType: "graduation", language: "ar", citationStyle: "APA7" }); toast({ title: "تم حفظ قالب البحث" }); }, onError: (error) => toast({ title: "تعذر حفظ القالب", description: apiErrorMessage(error), variant: "destructive" }) });
  if (mode === "universities") return <div className="space-y-5"><div><h2 className="text-xl font-bold">دليل الجامعات</h2><p className="mt-1 text-sm text-muted-foreground">مرجع موحد للجامعات والكليات ومتطلبات التوثيق.</p></div><div className="grid gap-4 rounded-xl bg-card p-4 shadow-sm sm:grid-cols-2 lg:grid-cols-5"><Input value={university.nameAr} onChange={(e) => setUniversity((c) => ({ ...c, nameAr: e.target.value }))} placeholder="اسم الجامعة بالعربية" /><Input value={university.nameEn} onChange={(e) => setUniversity((c) => ({ ...c, nameEn: e.target.value }))} placeholder="الاسم بالإنجليزية" /><Input value={university.country} onChange={(e) => setUniversity((c) => ({ ...c, country: e.target.value }))} placeholder="الدولة" /><Input value={university.city} onChange={(e) => setUniversity((c) => ({ ...c, city: e.target.value }))} placeholder="المدينة" /><Button disabled={university.nameAr.length < 2 || saveUniversity.isPending} onClick={() => saveUniversity.mutate()}>إضافة جامعة</Button></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{(catalog.data?.universities || []).map((item: any) => <div key={item.id} className="rounded-xl bg-card p-4 shadow-sm"><GraduationCap className="h-6 w-6 text-violet-500" /><h3 className="mt-3 font-bold">{item.nameAr}</h3><p className="text-sm text-muted-foreground">{item.nameEn || item.city || "—"}</p></div>)}</div></div>;
  if (["writers", "supervisors"].includes(mode)) return <div className="space-y-5"><div><h2 className="text-xl font-bold">{mode === "writers" ? "الكتّاب والمراجعين" : "المشرفون"}</h2><p className="mt-1 text-sm text-muted-foreground">يعتمد هذا الدليل على موظفي AJN الحاليين ولا ينشئ حسابات مكررة.</p></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{(catalog.data?.writers || []).map((item: any) => <div key={item.id} className="rounded-xl bg-card p-4 shadow-sm"><UserRoundCheck className="h-6 w-6 text-violet-500" /><h3 className="mt-3 font-bold">{item.name || item.username}</h3><p className="text-sm text-muted-foreground">{item.role}</p></div>)}</div></div>;
  if (mode === "templates") return <div className="space-y-5"><div><h2 className="text-xl font-bold">قوالب الأبحاث</h2><p className="mt-1 text-sm text-muted-foreground">هيكل محفوظ للفصول واللغة ونمط التوثيق، قابل لإعادة الاستخدام.</p></div><div className="grid gap-3 rounded-xl bg-card p-4 shadow-sm md:grid-cols-5"><Input value={template.name} onChange={(e) => setTemplate((current) => ({ ...current, name: e.target.value }))} placeholder="اسم القالب" /><Input value={template.code} onChange={(e) => setTemplate((current) => ({ ...current, code: e.target.value }))} placeholder="الكود (اختياري)" /><Select value={template.researchType} onValueChange={(value) => setTemplate((current) => ({ ...current, researchType: value }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{Object.entries(TYPE_LABELS).map(([value, label]) => <SelectItem key={value} value={value}>{label}</SelectItem>)}</SelectContent></Select><Select value={template.citationStyle} onValueChange={(value) => setTemplate((current) => ({ ...current, citationStyle: value }))}><SelectTrigger><SelectValue /></SelectTrigger><SelectContent>{["APA7", "IEEE", "MLA", "Harvard", "Chicago"].map((style) => <SelectItem key={style} value={style}>{style}</SelectItem>)}</SelectContent></Select><Button disabled={template.name.trim().length < 2 || saveTemplate.isPending} onClick={() => saveTemplate.mutate()}>حفظ القالب</Button></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{(catalog.data?.templates || []).map((item: any) => <div key={item.id} className="rounded-xl bg-card p-4 shadow-sm"><FileCheck2 className="h-6 w-6 text-violet-500" /><h3 className="mt-3 font-bold">{item.name}</h3><p className="text-sm text-muted-foreground">{item.code} · {item.citationStyle}</p></div>)}</div></div>;
  if (mode === "portal") return <div className="rounded-xl bg-card p-8 text-center shadow-sm"><QrCode className="mx-auto h-10 w-10 text-violet-500" /><h2 className="mt-4 text-xl font-bold">بوابة متابعة الزبون</h2><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-muted-foreground">بوابة آمنة برمز QR لكل بحث، تعرض التقدم والفصول والملفات العامة والاستلال والفاتورة والمراسلات.</p><Button className="mt-5" asChild><a href="/research" target="_blank">فتح البوابة</a></Button></div>;
  if (mode === "settings") { const integrations = catalog.data?.integrations || {}; return <div className="space-y-5"><div><h2 className="text-xl font-bold">تكاملات مركز الأبحاث</h2><p className="mt-1 text-sm text-muted-foreground">حالة الربط مع خدمات AJN ومصادر البحث الخارجية.</p></div><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">{[["المساعد الذكي", integrations.ai], ["Supabase Storage", integrations.storage], ["Semantic Scholar API", true], ["PubMed / NCBI", true]].map(([label, active]) => <div key={String(label)} className="rounded-xl bg-card p-4 shadow-sm"><div className="flex items-center justify-between"><strong>{String(label)}</strong><Badge variant={active ? "default" : "secondary"}>{active ? "متصل" : "يحتاج إعداد"}</Badge></div></div>)}</div></div>; }
  return <div className="rounded-xl bg-card p-8 text-center shadow-sm"><Settings className="mx-auto h-10 w-10 text-violet-500" /><h2 className="mt-4 text-xl font-bold">{MODES[mode] || mode}</h2><p className="mx-auto mt-2 max-w-xl text-sm leading-6 text-muted-foreground">هذه الصفحة مرتبطة بمركز الأبحاث وتستخدم القوالب والصلاحيات والإعدادات العامة الحالية. تُدار البيانات من سجل الطلب المركزي.</p></div>;
}

export default function ResearchCenterPage() {
  const mode = modeFromPath(); const title = MODES[mode] || MODES.dashboard;
  const content = mode === "dashboard" || mode === "reports" ? <Dashboard /> : mode === "new" ? <OrderForm /> : ["orders", "plagiarism", "citations"].includes(mode) ? <Orders /> : mode === "library" ? <Orders library /> : mode === "sources" ? <SourcesCenter /> : mode === "ai" ? <AiCenter /> : ["writers", "supervisors", "universities", "templates", "portal", "settings"].includes(mode) ? <CatalogPage mode={mode} /> : <Dashboard />;
  return <main dir="rtl" className="min-h-full bg-muted/30 p-3 sm:p-5"><div className="mx-auto max-w-[1680px]"><header className="mb-5 flex flex-wrap items-center justify-between gap-3"><div className="flex items-center gap-3"><span className="flex h-11 w-11 items-center justify-center rounded-xl bg-violet-600 text-white"><GraduationCap className="h-6 w-6" /></span><div><p className="text-xs font-medium text-violet-600 dark:text-violet-300">AJN Research Center</p><h1 className="text-xl font-bold">{title}</h1></div></div><div className="flex gap-2"><Button variant="outline" asChild><a href="/research"><QrCode className="ml-2 h-4 w-4" />بوابة العميل</a></Button><Button asChild><a href="/admin/research/new"><Plus className="ml-2 h-4 w-4" />بحث جديد</a></Button></div></header>{content}</div></main>;
}
